"""The ``pennywise`` command line interface."""

import argparse
import csv
import io
import json
import os
import re
import sys

from . import __version__
from .ledger import ParseError, format_amount, format_entry, is_field, parse, parse_date
from .reports import balance, by_category, by_month, filter_entries

PROG = "pennywise"

EXIT_OK = 0
EXIT_LEDGER = 1
EXIT_USAGE = 2

# The same line ends the ledger parser recognises, as bytes.
_LINE_BREAK_BYTES_RE = re.compile(rb"\r\n|\r|\n")


class _LedgerError(Exception):
    """A mistake in the ledger or in the entry given to ``add`` (exit 1)."""


class _Parser(argparse.ArgumentParser):
    def error(self, message):
        self.print_usage(sys.stderr)
        self.exit(EXIT_USAGE, "%s: %s\n" % (PROG, message))


def _date_arg(text):
    try:
        return parse_date(text)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(str(exc)) from None


def _build_parser():
    parser = _Parser(
        prog=PROG, description="Report where the money went from a plain-text ledger.", allow_abbrev=False
    )
    parser.add_argument("--version", action="version", version="%s %s" % (PROG, __version__))
    commands = parser.add_subparsers(dest="command", metavar="COMMAND", parser_class=_Parser)
    commands.required = True

    p = commands.add_parser("balance", help="print the total of all entries", allow_abbrev=False)
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = commands.add_parser("summary", help="print totals per category or month", allow_abbrev=False)
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--by", choices=("category", "month"), default="category")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = commands.add_parser("list", help="print entries, oldest first", allow_abbrev=False)
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--category", metavar="C")
    p.add_argument("--since", metavar="DATE", type=_date_arg)
    p.add_argument("--until", metavar="DATE", type=_date_arg)
    p.add_argument("--json", action="store_true", help="print JSON")

    p = commands.add_parser("add", help="append an entry to the ledger", allow_abbrev=False)
    p.add_argument("file", metavar="FILE")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?", default="")

    p = commands.add_parser("export", help="print entries as CSV, in list order", allow_abbrev=False)
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--format", choices=("csv",), default="csv")
    return parser, commands.choices


def _read_text(path):
    if path == "-":
        stream = sys.stdin
        if stream is None:
            # Standard input was closed before the program started.
            raise OSError("it is closed")
        data = stream.buffer.read() if hasattr(stream, "buffer") else stream.read()
    else:
        with open(path, "rb") as handle:
            data = handle.read()
    if isinstance(data, bytes):
        # Strip one leading byte-order mark by hand: utf-8-sig reports error offsets after it.
        if data.startswith(b"\xef\xbb\xbf"):
            data = data[3:]
        try:
            data = data.decode("utf-8")
        except UnicodeDecodeError as exc:
            line = len(_LINE_BREAK_BYTES_RE.findall(data[: exc.start])) + 1
            raise ValueError("line %d is not valid UTF-8" % line) from None
    return data


def _load(path):
    try:
        text = _read_text(path)
    except (OSError, ValueError) as exc:
        name = "standard input" if path == "-" else path
        raise OSError("cannot read %s: %s" % (name, _reason(exc))) from None
    try:
        return parse(text)
    except ParseError as exc:
        raise _LedgerError(str(exc)) from None


def _sorted(entries):
    return sorted(entries, key=lambda e: e.date)


def _as_json(value):
    return json.dumps(value, ensure_ascii=False) + "\n"


def _entry_dict(entry):
    return {
        "date": entry.date.isoformat(),
        "category": entry.category,
        "amount": format_amount(entry.amount),
        "note": entry.note,
    }


def _cmd_balance(args):
    total = format_amount(balance(_load(args.file)))
    return _as_json({"balance": total}) if args.json else total + "\n"


def _cmd_summary(args):
    entries = _load(args.file)
    totals = by_category(entries) if args.by == "category" else by_month(entries)
    rows = [(name, format_amount(totals[name])) for name in sorted(totals)]
    if args.json:
        return _as_json(dict(rows))
    return "".join("%s  %s\n" % row for row in rows)


def _cmd_list(args):
    entries = filter_entries(_load(args.file), args.category, args.since, args.until)
    entries = _sorted(entries)
    if args.json:
        return _as_json([_entry_dict(e) for e in entries])
    return "".join(format_entry(e) + "\n" for e in entries)


def _cmd_export(args):
    entries = _sorted(_load(args.file))
    out = io.StringIO()
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in entries:
        d = _entry_dict(e)
        writer.writerow([d["date"], d["category"], d["amount"], d["note"]])
    return out.getvalue()


def _cmd_add(args):
    for name, value in (("date", args.date), ("category", args.category), ("amount", args.amount)):
        if not is_field(value):
            raise _LedgerError("line 1: %s must be a single word, got %r" % (name, value))
    try:
        # A DATE starting with '#' would make the built line a comment, so check it directly.
        parse_date(args.date)
    except ValueError as exc:
        raise _LedgerError("line 1: %s" % exc) from None
    line = "%s %s %s" % (args.date, args.category, args.amount)
    if args.note:
        line += " " + args.note
    if "\n" in line or "\r" in line:
        raise _LedgerError("line 1: entry must not contain a line break")
    try:
        entries = parse(line)
    except ParseError as exc:
        raise _LedgerError(str(exc)) from None
    if len(entries) != 1:
        raise _LedgerError("line 1: expected 'DATE CATEGORY AMOUNT [NOTE]', got %r" % line)
    canonical = format_entry(entries[0])
    try:
        encoded = canonical.encode("utf-8")
    except UnicodeEncodeError:
        raise _LedgerError("line 1: entry is not valid UTF-8 text") from None

    # Only touch the file once the entry is known to be valid and encodable.
    try:
        prefix = b""
        try:
            if os.path.getsize(args.file) > 0:
                with open(args.file, "rb") as handle:
                    handle.seek(-1, os.SEEK_END)
                    if handle.read(1) != b"\n":
                        prefix = b"\n"
        except FileNotFoundError:
            pass
        data = prefix + encoded + b"\n"
        with open(args.file, "ab") as handle:
            handle.write(data)
    except OSError as exc:
        raise OSError("cannot write %s: %s" % (args.file, _reason(exc))) from None
    return canonical + "\n"


_COMMANDS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "add": _cmd_add,
    "export": _cmd_export,
}


def _reason(exc):
    return exc.strerror if isinstance(exc, OSError) and exc.strerror else exc


def _complain(message):
    """Write a one-line error to stderr, if stderr is usable."""
    try:
        sys.stderr.write("%s: %s\n" % (PROG, message))
        sys.stderr.flush()
    except (OSError, ValueError, AttributeError):
        pass


def _silence_stdout():
    """Point stdout at the null device so the final flush at exit cannot fail."""
    try:
        os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


_HELP_FLAGS = ("-h", "--help")
_VALUE_OPTIONS = ("--by", "--category", "--since", "--until", "--format")


def _is_option(arg):
    """True for a word `add` must leave to argparse: help, or an unknown ``--long`` option."""
    return arg in _HELP_FLAGS or (arg.startswith("--") and len(arg) > 2)


def _protect_add(argv):
    """Put ``--`` before the positionals of ``add`` so values starting with ``-`` are kept.

    ``add`` takes no options besides help, so a DATE, CATEGORY, AMOUNT or NOTE that starts
    with a single ``-`` (``-1,000.00``, ``-food``) is data, and the entry parser judges it.
    Help and ``--long`` words given before the fourth positional stay options.
    """
    if "--" in argv:
        return argv
    seen = 0
    last_option = 0
    for index in range(1, len(argv)):
        if _is_option(argv[index]):
            last_option = index
        else:
            seen += 1
            if seen == 4:
                break
    return argv[: last_option + 1] + ["--"] + argv[last_option + 1 :]


def _protect_file(argv):
    """Let a read command take a FILE starting with a single ``-`` (``balance -x``).

    Such a word is moved behind ``--`` at the end, so options may still follow or precede it.
    """
    if "--" in argv:
        return argv
    keep, moved = [argv[0]], []
    for index in range(1, len(argv)):
        arg = argv[index]
        value_of_option = argv[index - 1] in _VALUE_OPTIONS
        if arg.startswith("-") and not arg.startswith("--") and arg != "-" and arg != "-h" and not value_of_option:
            moved.append(arg)
        else:
            keep.append(arg)
    return keep + ["--"] + moved if moved else argv


def _protect_dashes(argv):
    argv = list(argv)
    if not argv:
        return argv
    if argv[0] == "add":
        return _protect_add(argv)
    if argv[0] in ("balance", "summary", "list", "export"):
        return _protect_file(argv)
